// Stand-in for @minecraft/server-ui: forms answer from a queue the test fills.
export const answers = [];
export const shown = [];
export const FormCancelationReason = { UserBusy: 'UserBusy', UserClosed: 'UserClosed' };
class Base {
  constructor() { this.items = []; }
  title(t) { this._title = t; return this; }
  body(t) { this.items.push(['body', t]); return this; }
  label(t) { this.items.push(['label', t]); return this; }
  header(t) { this.items.push(['header', t]); return this; }
  divider() { this.items.push(['divider']); return this; }
  async show() {
    shown.push(this);
    const a = answers.shift();
    if (a === undefined) return { canceled: true, cancelationReason: 'UserClosed' };
    return typeof a === 'function' ? a(this) : a;
  }
}
export class ActionFormData extends Base { button(t, i) { this.items.push(['button', t, i]); return this; } }
export class MessageFormData extends Base { button1(t) { return this; } button2(t) { return this; } }
export class ModalFormData extends Base {
  textField(l, p, o = {}) { this.items.push(['text', l, o.defaultValue ?? '']); return this; }
  dropdown(l, opts, o = {}) { this.items.push(['dropdown', l, o.defaultValueIndex ?? 0, opts]); return this; }
  slider(l, min, max, o = {}) { this.items.push(['slider', l, o.defaultValue ?? min, min, max]); return this; }
  toggle(l, o = {}) { this.items.push(['toggle', l, !!o.defaultValue]); return this; }
  submitButton() { return this; }
  /** test helper: default values of every input, with overrides by label substring */
  defaults(over = {}) {
    const vals = [];
    for (const it of this.items) {
      if (['label', 'header', 'divider', 'body'].includes(it[0])) { vals.push(undefined); continue; }
      let v = it[2];
      for (const [k, ov] of Object.entries(over)) if (String(it[1]).includes(k)) v = ov;
      vals.push(v);
    }
    return { canceled: false, formValues: vals };
  }
}
